import { Linking, Platform, View } from 'react-native';

import { reportError } from '@/lib/logger';
import { Button, useTheme } from '@/ui';

import { LEGAL_DOC_TITLES, LEGAL_DOC_KINDS } from '../constants';
import { LegalLinks } from './LegalLinks';

/**
 * The welcome screen's footer. Native: the in-app documents. Web: the static
 * pages `/privacy.html` and `/terms.html` (generated by `npm run legal:build`),
 * which open in a new tab and also work without loading the app.
 */
export function WelcomeLegalLinks() {
  const { spacing } = useTheme();
  if (Platform.OS !== 'web') return <LegalLinks />;
  return (
    <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: spacing.xs, justifyContent: 'center' }}>
      {LEGAL_DOC_KINDS.map((kind) => (
        <Button
          key={kind}
          label={LEGAL_DOC_TITLES[kind]}
          variant="ghost"
          size="sm"
          icon="external-link"
          accessibilityHint="Opens the page in a new tab"
          onPress={() => {
            Linking.openURL(`/${kind}.html`).catch((error: unknown) => reportError('legal.openStatic', error));
          }}
        />
      ))}
    </View>
  );
}
